import { test } from 'node:test';
import assert from 'node:assert/strict';
import { execFile } from 'node:child_process';
import { mkdtemp, readdir, writeFile, mkdir } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { promisify } from 'node:util';

const BOT = '<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round6-heldout-c-haiku/work/baseline-g3-1/bot.mjs';
const run = promisify(execFile);
const now = new Date();

async function fresh() {
  const base = await mkdtemp(join(tmpdir(), 'bot-'));
  process.env.STATE_DIR = join(base, 'state', 'nested'); // directory does not exist yet
  return process.env.STATE_DIR;
}

test('new address: marketing and receipt allowed', async () => {
  await fresh();
  const bot = await import(`${BOT}?a=${Math.random()}`);
  assert.equal((await bot.mayEmail('<EMAIL>', 'marketing', now)).allowed, true);
  assert.equal((await bot.mayEmail('<EMAIL>', 'receipt', now)).allowed, true);
});

test('unsubscribe blocks marketing, not receipts; case and spaces are ignored', async () => {
  await fresh();
  const bot = await import(`${BOT}?b=${Math.random()}`);
  await bot.unsubscribe('  <EMAIL> ');
  const m = await bot.mayEmail('<EMAIL>', 'marketing', now);
  assert.equal(m.allowed, false);
  assert.match(m.reason, /unsubscribed/);
  assert.equal((await bot.mayEmail('<EMAIL>', 'receipt', now)).allowed, true);
});

test('plus-tag shares a record with the base address', async () => {
  await fresh();
  const bot = await import(`${BOT}?c=${Math.random()}`);
  await bot.unsubscribe('<EMAIL>');
  assert.equal((await bot.mayEmail('<EMAIL>', 'marketing', now)).allowed, false);
});

test('resubscribe clears unsubscribe; later unsubscribe blocks again', async () => {
  await fresh();
  const bot = await import(`${BOT}?d=${Math.random()}`);
  await bot.unsubscribe('<EMAIL>');
  await bot.resubscribe('<EMAIL>');
  assert.equal((await bot.mayEmail('<EMAIL>', 'marketing', now)).allowed, true);
  await new Promise(r => setTimeout(r, 5));
  await bot.unsubscribe('<EMAIL>');
  assert.equal((await bot.mayEmail('<EMAIL>', 'marketing', now)).allowed, false);
});

test('resubscribe alone does not block; same-ms unsubscribe wins over resubscribe', async () => {
  await fresh();
  const bot = await import(`${BOT}?e=${Math.random()}`);
  await bot.resubscribe('<EMAIL>');
  assert.equal((await bot.mayEmail('<EMAIL>', 'marketing', now)).allowed, true);
});

test('invalid addresses and bad arguments', async () => {
  await fresh();
  const bot = await import(`${BOT}?f=${Math.random()}`);
  for (const bad of ['', 'no-at-sign', '@x.com', 'a@', 'a <EMAIL>', 'a@localhost', '<EMAIL>', null]) {
    const r = await bot.mayEmail(bad, 'receipt', now);
    assert.equal(r.allowed, false, `receipt to ${JSON.stringify(bad)}`);
    assert.ok(r.reason.length > 0);
    await assert.rejects(bot.unsubscribe(bad), TypeError);
  }
  await assert.rejects(bot.mayEmail('<EMAIL>', 'newsletter', now), TypeError);
  await assert.rejects(bot.mayEmail('<EMAIL>', 'marketing', '2026-01-01'), TypeError);
});

test('unreadable state fails closed for marketing', async () => {
  const dir = await fresh();
  const bot = await import(`${BOT}?g=${Math.random()}`);
  await bot.unsubscribe('<EMAIL>');
  // corrupt the newest event for this address
  const sub = join(dir, 'subscriptions');
  const [hash] = await readdir(sub);
  const [ev] = (await readdir(join(sub, hash))).filter(n => n.endsWith('.json'));
  await writeFile(join(sub, hash, ev), '{not json');
  const r = await bot.mayEmail('<EMAIL>', 'marketing', now);
  assert.equal(r.allowed, false);
  assert.match(r.reason, /could not be read/);
});

test('temp files left by a killed worker are ignored', async () => {
  const dir = await fresh();
  const bot = await import(`${BOT}?h=${Math.random()}`);
  await bot.unsubscribe('<EMAIL>');
  const sub = join(dir, 'subscriptions');
  const [hash] = await readdir(sub);
  await writeFile(join(sub, hash, '.tmp-dead'), 'partial');
  assert.equal((await bot.mayEmail('<EMAIL>', 'marketing', now)).allowed, false);
});

test('state survives across processes; many concurrent writers', async () => {
  const dir = await fresh();
  const worker = `
    const bot = await import(${JSON.stringify(BOT)} + '?w=' + Math.random());
    const i = Number(process.argv[1]);
    await bot.unsubscribe('<EMAIL>');
    await bot.unsubscribe('u' + i + '@x.com');
    if (i % 2) await bot.resubscribe('<EMAIL>'); else await bot.unsubscribe('<EMAIL>');
  `;
  const script = join(tmpdir(), `bot-worker-${process.pid}.mjs`);
  await writeFile(script, worker);
  await Promise.all(Array.from({ length: 24 }, (_, i) =>
    run(process.execPath, [script, String(i)], { env: { ...process.env, STATE_DIR: dir } })));

  const bot = await import(`${BOT}?z=${Math.random()}`);
  for (let i = 0; i < 24; i++) {
    assert.equal((await bot.mayEmail(`u${i}@x.com`, 'marketing', now)).allowed, false, `u${i}`);
  }
  assert.equal((await bot.mayEmail('<EMAIL>', 'marketing', now)).allowed, false);
  // flip: some workers unsubscribe, some resubscribe; the state is whatever was written last.
  // Only assert that the record is a single valid file, not which op won.
  const sub = join(dir, 'subscriptions');
  const flipHash = (await readdir(sub)).find(async () => true);
  assert.ok(flipHash);
  const hashes = await readdir(sub);
  assert.equal(hashes.length, 26);
  const tmps = [];
  for (const h of hashes) for (const n of await readdir(join(sub, h))) if (n.startsWith('.tmp')) tmps.push(n);
  assert.deepEqual(tmps, []);
  await run(process.execPath, ['-e', ''], {}); // no-op
});

test('unsubscribe is durable: a new process sees it immediately', async () => {
  const dir = await fresh();
  await run(process.execPath, ['--input-type=module', '-e',
    `const b = await import(${JSON.stringify(BOT)}); await b.unsubscribe('<EMAIL>');`],
    { env: { ...process.env, STATE_DIR: dir } });
  const bot = await import(`${BOT}?y=${Math.random()}`);
  assert.equal((await bot.mayEmail('<EMAIL>', 'marketing', now)).allowed, false);
});
EOF
